-- stray – englische Texte (Teil 13), Schlüssel = deutscher Originaltext
local _, ns = ...
local E = ns.LocaleEN

-- DMG-Meter: mehrere Fenster (0.23.0-alpha)
E["DMG-Meter %d"] = "Damage Meter %d"
E["„+“ im Kopf: weiteres Fenster (bis zu 5), dockt oben an."] = "“+” in the header: another window (up to 5), docks on top."
E["An die Ober- oder Unterkante eines anderen DMG-Meters ziehen: andocken. Wegziehen löst es wieder."] = "Drag to the top or bottom edge of another damage meter to dock. Drag away to undock."
E["Löscht alle Kämpfe in allen DMG-Meter-Fenstern – auch in Blizzards eigenem Schadensmesser. Geht nur außerhalb des Kampfes."] = "Clears all fights in all damage meter windows – including Blizzard's own damage meter. Only works out of combat."
E["Weiteres Fenster"] = "Another window"
E["Öffnet eine Kopie dieses Fensters (gleiche Größe, gleicher Modus) und dockt sie oben an. Bis zu 5 Fenster."] = "Opens a copy of this window (same size, same mode) docked on top. Up to 5 windows."
E["Fenster schließen"] = "Close window"
E["Schließt dieses DMG-Meter-Fenster. Angedockte Fenster rücken nach."] = "Closes this damage meter window. Docked windows move up to fill the gap."
E["Anzahl Fenster"] = "Number of windows"
E["Wie viele DMG-Meter-Fenster offen sind (1–5). Weitere Fenster öffnest du auch mit „+“ im Kopf eines Fensters, schließen mit „ד. Ein neues Fenster ist eine Kopie (gleiche Größe, gleicher Modus) und dockt oben an. Mit Shift + ziehen oder im Bearbeitungsmodus löst du ein Fenster; an Ober- oder Unterkante eines anderen Fensters gezogen, dockt es wieder an. Angedockte Fenster wandern mit, angedockt änderst du nur die Höhe. Zurücksetzen gilt für alle Fenster."] = "How many damage meter windows are open (1–5). You can also open more with “+” in a window's header and close them with “×”. A new window is a copy (same size, same mode) and docks on top. Shift + drag or Edit Mode undocks a window; drag it to the top or bottom edge of another window to dock it again. Docked windows move together; when docked you only change the height. Reset applies to all windows."
E["Modus"] = "Mode"
E["Schaden oder Heilung im gewählten DMG-Meter-Fenster – dasselbe wie S || H im Fenster selbst."] = "Damage or healing in the selected damage meter window – same as D || H in the window itself."
